/**
 * SessionFactory — creates and persists identity sessions.
 *
 * This exists as its own collaborator because creating a session requires
 * three things the authentication service should not own: generating the
 * opaque token, deriving the session id, and persisting the row.
 *
 * The token is generated by an injected generator, so the domain never
 * imports `crypto` — the domain remains dependency-free (see the technical
 * design's layer rules).
 */
import { randomUUID } from 'node:crypto';
import { IdentitySession } from '../entities/identity-session.js';
import { Operator } from '../entities/operator.js';
import { SessionToken } from '../value-objects/session-token.js';
import { AuthenticationMethod } from '../value-objects/authentication-method.js';
import type { SessionRepository } from '../ports/repositories.js';

/** Generates a high-entropy opaque token. */
export type SessionTokenGenerator = () => SessionToken;

export class SessionFactory {
  constructor(
    private readonly sessions: SessionRepository,
    private readonly generateToken: SessionTokenGenerator,
    private readonly generateId: () => string = randomUUID,
  ) {}

  async create(
    operator: Operator,
    authenticatedAt: Date,
    expiresAt: Date,
    method: AuthenticationMethod = AuthenticationMethod.local(),
  ): Promise<IdentitySession> {
    const session = new IdentitySession(
      this.generateId(),
      operator.id,
      // INVARIANT I-4: the role comes from the operator resolved by the
      // provider, which read it from the matched credential row. It is
      // never read from the request.
      operator.role,
      method,
      this.generateToken(),
      authenticatedAt,
      expiresAt,
    );
    await this.sessions.save(session);
    return session;
  }
}
